const raw = $input.first().json;

if (!raw || !Array.isArray(raw.stations)) {
  throw new Error('Unexpected API response shape: missing stations array.');
}

const stations = raw.stations.map(s => ({
  stationId: s.stationId || s.station_id || s.id,
  location: s.location || s.address || '',
  currentDemandKw: parseFloat(s.currentDemandKw || s.current_demand_kw || s.power_kw) || 0,
  connectedVehicles: parseInt(s.connectedVehicles || s.connected_vehicles || s.plugged_in_count, 10) || 0,
  avgVehicleBatteryPct: (s.avgVehicleBatteryPct ?? s.avg_battery_pct) !== undefined
    ? parseFloat(s.avgVehicleBatteryPct ?? s.avg_battery_pct)
    : null,
  maxCapacityKw: parseFloat(s.maxCapacityKw || s.max_capacity_kw || s.rated_kw) || 0,
  priorityQueueCount: parseInt(s.priorityQueueCount || s.priority_queue_count, 10) || 0
}));

const gridCapacityKw = parseFloat(raw.gridCapacityKw || raw.grid_capacity_kw) || 0;
const currentTariffRatePerKwh = parseFloat(raw.currentTariffRatePerKwh || raw.tariff_rate) || 0;
const tariffPeriod = raw.tariffPeriod || raw.tariff_period || 'off-peak';
const peakTariffRatePerKwh = parseFloat(raw.peakTariffRatePerKwh || raw.peak_tariff_rate) || currentTariffRatePerKwh;

return [{
  json: {
    stations,
    stationCount: stations.length,
    gridCapacityKw,
    currentTariffRatePerKwh,
    tariffPeriod,
    peakTariffRatePerKwh
  }
}];

const item = $input.first().json;
const config = $('Config - Thresholds & Site Settings').first().json;
const stations = item.stations || [];

const totalDemandKw = Math.round(stations.reduce((sum, s) => sum + s.currentDemandKw, 0) * 10) / 10;
const gridCapacityKw = item.gridCapacityKw || 1;
const gridLoadPct = Math.round((totalDemandKw / gridCapacityKw) * 1000) / 10;
const headroomKw = Math.round((gridCapacityKw - totalDemandKw) * 10) / 10;

const isPeakTariff = item.tariffPeriod === 'peak';

let gridStatus = 'Normal';
if (gridLoadPct >= config.gridOverloadThresholdPct) gridStatus = 'Overload Risk';
else if (gridLoadPct >= config.gridHighThresholdPct) gridStatus = 'High Load';
else if (gridLoadPct >= config.gridModerateThresholdPct) gridStatus = 'Moderate Load';

// Anomaly / spike detection using workflow static data (persists between scheduled runs)
const staticData = $getWorkflowStaticData('node');
if (!staticData.history) staticData.history = [];

const previousReading = staticData.history.length > 0 ? staticData.history[staticData.history.length - 1] : null;
let demandSpikeDetected = false;
let demandChangePct = 0;
if (previousReading && previousReading.totalDemandKw > 0) {
  demandChangePct = Math.round(((totalDemandKw - previousReading.totalDemandKw) / previousReading.totalDemandKw) * 1000) / 10;
  demandSpikeDetected = demandChangePct >= 25;
}

staticData.history.push({ timestamp: new Date().toISOString(), totalDemandKw, gridLoadPct });
if (staticData.history.length > 24) staticData.history.shift(); // ~2 hours of history at 5-min cycles

return [{
  json: {
    ...item,
    totalDemandKw,
    gridLoadPct,
    headroomKw,
    isPeakTariff,
    gridStatus,
    demandSpikeDetected,
    demandChangePct,
    readingHistory: staticData.history
  }
}];

const item = $input.first().json;
const config = $('Config - Thresholds & Site Settings').first().json;
const history = item.readingHistory || [];

let forecastedDemandKw = item.totalDemandKw;
let trendSlopeKwPerMin = 0;

if (history.length >= 3) {
  // Simple linear regression over the last ~6 readings (~30 min at 5-min cycles)
  const points = history.slice(-6);
  const n = points.length;
  const xs = points.map((_, i) => i * 5);
  const ys = points.map(p => p.totalDemandKw);
  const xMean = xs.reduce((a, b) => a + b, 0) / n;
  const yMean = ys.reduce((a, b) => a + b, 0) / n;
  let num = 0, den = 0;
  for (let i = 0; i < n; i++) {
    num += (xs[i] - xMean) * (ys[i] - yMean);
    den += (xs[i] - xMean) ** 2;
  }
  trendSlopeKwPerMin = den !== 0 ? num / den : 0;
  forecastedDemandKw = Math.max(0, Math.round((item.totalDemandKw + trendSlopeKwPerMin * config.forecastWindowMinutes) * 10) / 10);
}

const forecastedLoadPct = Math.round((forecastedDemandKw / item.gridCapacityKw) * 1000) / 10;
const forecastOverloadRisk = forecastedLoadPct >= config.forecastOverloadBufferPct;

return [{
  json: {
    ...item,
    trendSlopeKwPerMin: Math.round(trendSlopeKwPerMin * 100) / 100,
    forecastedDemandKw,
    forecastedLoadPct,
    forecastOverloadRisk
  }
}];

const item = $input.first().json;
const config = $('Config - Thresholds & Site Settings').first().json;
const stations = item.stations || [];
const isPeakTariff = item.isPeakTariff;
const gridStatus = item.gridStatus;
const forecastOverloadRisk = item.forecastOverloadRisk;

// Use the more conservative of current headroom and forecasted headroom
const forecastedHeadroomKw = Math.round((item.gridCapacityKw - item.forecastedDemandKw) * 10) / 10;
let remainingHeadroom = Math.min(item.headroomKw, forecastedHeadroomKw);

function urgencyScore(s) {
  const batteryPct = s.avgVehicleBatteryPct ?? 100;
  const batteryUrgency = Math.max(0, (config.lowBatteryThresholdPct * 3) - batteryPct);
  const queueUrgency = s.priorityQueueCount * 15;
  return batteryUrgency + queueUrgency;
}

const scored = stations
  .map(s => ({ ...s, urgencyScore: Math.round(urgencyScore(s) * 10) / 10 }))
  .sort((a, b) => b.urgencyScore - a.urgencyScore);

const schedule = scored.map(s => {
  const highPriority = s.priorityQueueCount > 0 || (s.avgVehicleBatteryPct !== null && s.avgVehicleBatteryPct < config.lowBatteryThresholdPct);

  let action = 'Charge Now';
  let reason = 'Sufficient grid headroom and acceptable tariff.';

  if ((gridStatus === 'Overload Risk' || forecastOverloadRisk) && !highPriority) {
    action = 'Delay to Off-Peak';
    reason = (forecastOverloadRisk && gridStatus !== 'Overload Risk')
      ? 'Forecasted demand trend threatens grid capacity; deferring non-urgent charging pre-emptively.'
      : 'Grid near capacity; deferring non-urgent charging.';
  } else if (isPeakTariff && !highPriority) {
    action = 'Throttle (50%)';
    reason = 'Peak tariff window; reducing rate for non-urgent vehicles.';
  } else if (s.currentDemandKw > remainingHeadroom && !highPriority) {
    action = 'Throttle (50%)';
    reason = 'Limited remaining grid headroom at this station.';
  }

  if (action === 'Charge Now') {
    remainingHeadroom -= s.currentDemandKw;
  } else if (action.startsWith('Throttle')) {
    remainingHeadroom -= s.currentDemandKw * 0.5;
  }

  const estimatedCostPerHourUsd = Math.round(s.currentDemandKw * item.currentTariffRatePerKwh * 100) / 100;

  return {
    stationId: s.stationId,
    location: s.location,
    connectedVehicles: s.connectedVehicles,
    avgVehicleBatteryPct: s.avgVehicleBatteryPct,
    priorityQueueCount: s.priorityQueueCount,
    urgencyScore: s.urgencyScore,
    recommendedAction: action,
    reason,
    estimatedCostPerHourUsd
  };
});

return [{
  json: { ...item, schedule }
}];

const item = $input.first().json;
const config = $('Config - Thresholds & Site Settings').first().json;
const schedule = item.schedule || [];

const delayedStations = schedule.filter(s => s.recommendedAction === 'Delay to Off-Peak');
const throttledStations = schedule.filter(s => s.recommendedAction.startsWith('Throttle'));
const chargingNowStations = schedule.filter(s => s.recommendedAction === 'Charge Now');

const estimatedLoadReductionKw = Math.round(
  (
    delayedStations.reduce((sum, s) => sum + s.currentDemandKw, 0) +
    throttledStations.reduce((sum, s) => sum + s.currentDemandKw * 0.5, 0)
  ) * 10
) / 10;

const projectedGridLoadPct = Math.round(
  ((item.totalDemandKw - estimatedLoadReductionKw) / item.gridCapacityKw) * 1000
) / 10;

const avoidedTariffRate = item.isPeakTariff ? item.peakTariffRatePerKwh : item.currentTariffRatePerKwh;
const costSavingsPerHourUsd = Math.round(estimatedLoadReductionKw * avoidedTariffRate * 100) / 100;

const mitigationSummary =
  `Grid load at ${item.gridLoadPct}% (${item.gridStatus}), forecasted to reach ${item.forecastedLoadPct}% within ${config.forecastWindowMinutes} min. ` +
  `Delaying ${delayedStations.length} station(s) and throttling ${throttledStations.length} station(s) ` +
  `to cut roughly ${estimatedLoadReductionKw} kW, projecting load down to ${projectedGridLoadPct}%. ` +
  `Estimated cost avoidance: ~$${costSavingsPerHourUsd}/hr.`;

return [{
  json: {
    ...item,
    delayedStations,
    throttledStations,
    chargingNowStations,
    estimatedLoadReductionKw,
    projectedGridLoadPct,
    costSavingsPerHourUsd,
    mitigationSummary,
    controlPayloadGeneratedAt: new Date().toISOString()
  }
}];
